CREATE OR REPLACE FUNCTION public.whatsapp_prepare_reminders() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record;p record;today date:=(now() AT TIME ZONE 'America/Sao_Paulo')::date; BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.whatsapp_settings WHERE enabled) THEN RETURN; END IF;
 FOR a IN SELECT a.*,coalesce(c.phone,a.guest_phone) phone,coalesce(c.full_name,a.guest_name) name,s.name service_name,s.duration_minutes service_duration FROM public.appointments a LEFT JOIN public.profiles c ON c.id=a.client_id JOIN public.services s ON s.id=a.service_id WHERE a.status='confirmado' AND a.day=today+1 LOOP PERFORM public.whatsapp_enqueue(a.id||':reminder:'||a.day||':'||a.start_time,'reminder',jsonb_build_object('phone',a.phone,'name',a.name,'serviceName',a.service_name,'durationMinutes',a.service_duration,'appointmentId',a.id,'day',a.day,'start',a.start_time)); END LOOP;
 FOR p IN SELECT i.*,o.client_phone FROM public.store_order_installments i JOIN public.store_orders o ON o.id=i.order_id WHERE i.due_date=today-1 AND i.paid_at IS NULL AND i.merged_into_order_id IS NULL AND o.archived_at IS NULL AND i.amount_cents>coalesce(i.paid_amount_cents,0) LOOP PERFORM public.whatsapp_enqueue(p.id||':due:'||p.due_date,'due',jsonb_build_object('phone',p.client_phone,'installmentId',p.id,'dueDate',p.due_date,'number',p.number,'amountCents',p.amount_cents-coalesce(p.paid_amount_cents,0))); END LOOP; END $$;